const watchFix = (
  t: number,
  step: number,
  altitudeMeters: number,
  verticalAccuracyM: number,
  speedMps: number,
  values: Partial<GpsRow> = {},
): GpsRow => ({
  t,
  producer: 'watch',
  latitude: 45,
  longitude: 7 + step * 0.00001,
  horizontalAccuracyM: 5,
  altitudeMeters,
  verticalAccuracyM,
  speedMps,
  speedAccuracyMps: 0.5,
  ...values,
});

const phoneFix = (t: number): GpsRow => ({
  t,
  producer: 'phone',
  latitude: 46,
  longitude: 8,
  horizontalAccuracyM: 3,
  altitudeMeters: 300,
  verticalAccuracyM: 2,
  speedMps: 9,
});

