const latest = (t: number, heartRateBpm: number): HealthRow => ({
  t,
  heartRateBpm,
  representation: 'builderMostRecent',
});
const energy = (t: number, activeEnergyKcal: number, representation = 'cumulativeWorkoutTotal'): HealthRow => ({
  t,
  activeEnergyKcal,
  representation,
});

